using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneSupportConversationSmoke:MonoBehaviour {
  static int checks;static string lastRoot;
  static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("Support ADV: "+label);}
  static CafeResponse Send(LocalCafeBackend b,string kind,string choice=null,int slot=1,string id=null,string request=null,int? revision=null){var s=b.Simulation.State;CafeResponse result=null;var call=b.Request("/commands",JsonUtility.ToJson(new PythonShiftCommand{request_id=request??Guid.NewGuid().ToString("N"),instance_id=s.instance_id,expected_revision=revision??s.revision,kind=kind,choice=choice,event_id=id??CafeEquipmentDialogue.EventId(s.day,"support"),save_slot=slot,save_id=slot.ToString(),working_cats=new string[0]}),r=>result=r);while(call.MoveNext()){}return result;}
  static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1){var r=Send(b,kind,choice,slot);Check(r.result==UnityWebRequest.Result.Success,kind+": "+r.error);}
  public static CafeRules Rules(){var r=StandaloneEquipmentConversationSmoke.Rules();return r;}
  static int Seed(CafeRules rules,bool consecutive=false){for(int seed=0;seed<100000;seed++){var s=new CafeSimulation(rules,seed,"free");if(s.CurrentStoreEvent.type=="support" && (!consecutive || CafeSimulation.StoreDraw(seed,2,"occur")<rules.store_events.probability && (int)(CafeSimulation.StoreDraw(seed,2,"type")*5)==4))return seed;}throw new Exception("support seed absent");}
  static void Setup(LocalCafeBackend b,bool consecutive=false){b.Simulation.Restore(new CafeSimulation(b.Simulation.Rules,Seed(b.Simulation.Rules,consecutive),"free").State);b.PrepareEquipmentConversation();}
  static string Facts(LocalCafeBackend b){var s=JsonUtility.FromJson<CafeSnapshot>(JsonUtility.ToJson(b.Simulation.State));s.revision=0;s.instance_id="";s.NormalizeJsonStrings();return JsonUtility.ToJson(s);}
  static void Finish(LocalCafeBackend b){var row=b.EquipmentConversation;row.progress.node=3;row.progress.page_offset=0;CafeEquipmentDialogue.Finish(row);b.RememberViewedConversations();}
  static void Legacy(LocalCafeBackend b,string folder,bool waiting){Good(b,"save_game",slot:6);var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-6.json")));old.equipment_conversations=null;old.equipment_conversation_selected=null;File.WriteAllText(Path.Combine(folder,"slot-6.json"),JsonUtility.ToJson(old));var fresh=new LocalCafeBackend(folder,b.Simulation.Rules);Good(fresh,"load_game",slot:6);Check(waiting?fresh.EquipmentConversations.Length==1 && !fresh.EquipmentResultPending:fresh.EquipmentConversations.All(r=>r.day!=1),"legacy invented result");Check(!fresh.EquipmentConversations.Any(r=>r.progress.completed),"legacy invented viewed branch");}
  public static int Run(string root){checks=0;root=Path.Combine(root,Guid.NewGuid().ToString("N"));lastRoot=root;Directory.CreateDirectory(root);
   foreach(string choice in new[]{"full","small","decline"}){
    var folder=Path.Combine(root,choice);var b=new LocalCafeBackend(folder,Rules());Setup(b,true);var row=b.EquipmentConversation;var view=b.View();var before=Facts(b);var rules=b.Simulation.Rules;var cost=choice=="full"?rules.store_events.support_full_cost:choice=="small"?rules.store_events.support_small_cost:0;var gain=choice=="full"?rules.store_events.support_full_popularity:choice=="small"?rules.store_events.support_small_popularity:0;
    Check(row.event_id=="support-request-1" && row.progress.conversation_id==CafeEquipmentDialogue.SupportId,"case identity");Check(view.store_event.choices.All(o=>o.can_select),"choices disabled");Check(view.store_event.choices[0].detail.Contains((b.Simulation.State.funds-rules.store_events.support_full_cost).ToString("0.#")),"funds preview missing");Check(Facts(b)==before,"preview mutates");Check(!view.day_off.can_select && view.day_off.reason.Contains("イベント"),"unanswered rest allowed/reason missing");Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success && Facts(b)==before,"rest skips answer");Legacy(b,folder,true);
    row.progress.node=1;row.progress.page_offset=2;Good(b,"save_game",slot:2);var fresh=new LocalCafeBackend(folder,Rules());Good(fresh,"load_game",slot:2);fresh.PrepareEquipmentConversation();Check(fresh.EquipmentConversation.progress.node==1 && fresh.EquipmentConversation.progress.page_offset==2,"intro restart");
    Check(Send(b,"resolve_store_event",choice,id:"support-request-2").result!=UnityWebRequest.Result.Success && Facts(b)==before,"wrong case accepted");double funds=b.Simulation.State.funds,pop=b.Simulation.State.popularity;int revision=b.Simulation.State.revision;string request=Guid.NewGuid().ToString("N");var response=Send(b,"resolve_store_event",choice,request:request,revision:revision);Check(response.result==UnityWebRequest.Result.Success,"answer failed");b.PrepareEquipmentConversation();
    Check(b.Simulation.State.funds==funds-cost && b.Simulation.State.expenses==cost && b.Simulation.State.popularity==pop && b.Simulation.CurrentStoreEvent.popularity==gain,"immediate/delayed effects");Check(b.EquipmentResultPending && b.EquipmentConversation.progress.branch_id==choice,"result missing");before=Facts(b);
    Check(Send(b,"resolve_store_event",choice,request:request,revision:revision).result==UnityWebRequest.Result.Success && Facts(b)==before,"idempotent retry");Check(Send(b,"resolve_store_event",choice).result!=UnityWebRequest.Result.Success && Facts(b)==before,"double answer");foreach(string cmd in new[]{"day_off","start_business","continue_goal","resolve_growth","step_autoplay"})Check(Send(b,cmd).result!=UnityWebRequest.Result.Success && Facts(b)==before,"result bypass "+cmd);
    b.EquipmentConversation.progress.node=1;b.EquipmentConversation.progress.page_offset=3;Good(b,"save_game",slot:3);fresh=new LocalCafeBackend(folder,Rules());Good(fresh,"load_game",slot:3);fresh.PrepareEquipmentConversation();Check(fresh.EquipmentResultPending && fresh.EquipmentConversation.progress.node==1 && fresh.EquipmentConversation.progress.page_offset==3,"result position restart");if(Facts(fresh)!=before){File.WriteAllText(Path.Combine(folder,"facts-before.json"),before);File.WriteAllText(Path.Combine(folder,"facts-after.json"),Facts(fresh));}Check(Facts(fresh)==before,"result facts restart");
    Check(!b.Replays.Load().entries.Any(e=>e.conversation_id==CafeEquipmentDialogue.SupportId),"unread Extra unlocked");Finish(b);Check(!b.EquipmentResultPending && Facts(b)==before,"reading changes state");Check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafeEquipmentDialogue.SupportId && e.branch_id==choice),"Extra absent");Legacy(b,folder,false);
    Good(b,"day_off");Check(b.Simulation.State.day==2 && b.Simulation.State.popularity==Math.Min(rules.popularity.cap,pop+gain),"closing popularity");b.PrepareEquipmentConversation();Check(b.EquipmentConversation.event_id=="support-request-2" && b.EquipmentConversation.progress.branch_id=="introduction","next day mixed");Good(b,"resolve_store_event","decline");b.PrepareEquipmentConversation();Finish(b);Good(b,"save_game",slot:4);Good(b,"load_game",slot:4);Check(b.EquipmentConversations.Count(r=>r.progress.completed)==2,"history lost");
   }
   foreach(string choice in new[]{"full","small"})foreach(int offset in new[]{-1,0,1}){
    var r=Rules();double cost=choice=="full"?r.store_events.support_full_cost:r.store_events.support_small_cost;r.starting_funds=cost+offset;var b=new LocalCafeBackend(Path.Combine(root,choice+offset),r);Setup(b);var option=b.View().store_event.choices[choice=="full"?0:1];Check(option.can_select,"new unaffordable restriction");Check(offset>0 || option.detail.Contains("経営終了"),"ending warning missing");Good(b,"resolve_store_event",choice);b.PrepareEquipmentConversation();Check(b.Simulation.State.funds==offset && (b.Simulation.State.game_over!=null)==(offset<=0) && b.EquipmentResultPending,"boundary ending");Good(b,"save_game",slot:3);var fresh=new LocalCafeBackend(Path.Combine(root,choice+offset),r);Good(fresh,"load_game",slot:3);fresh.PrepareEquipmentConversation();Check(fresh.EquipmentResultPending && fresh.Simulation.State.funds==offset,"ending restart");Finish(b);if(offset<=0)Check(b.OutcomePending && !b.EquipmentBlocksProgress,"ending lost");
   }
   var capRules=Rules();var cap=new LocalCafeBackend(Path.Combine(root,"cap"),capRules);Setup(cap);cap.Simulation.State.popularity=capRules.popularity.cap;Good(cap,"resolve_store_event","full");cap.PrepareEquipmentConversation();Finish(cap);Good(cap,"day_off");Check(cap.Simulation.State.popularity==capRules.popularity.cap,"cap changed");
   var growthRules=Rules();growthRules.growth.threshold=(int)growthRules.growth.rest_xp;var growth=new LocalCafeBackend(Path.Combine(root,"growth"),growthRules);Setup(growth);Good(growth,"resolve_store_event","decline");growth.PrepareEquipmentConversation();Finish(growth);Good(growth,"day_off");Check(growth.Simulation.GrowthWaiting && !growth.EquipmentResultPending,"growth blocked after result");
   var goalRules=Rules();goalRules.goal_stages[0].days=1;goalRules.goal_stages[0].target=10000;var goal=new LocalCafeBackend(Path.Combine(root,"goal"),goalRules);goal.Simulation.Restore(new CafeSimulation(goalRules,Seed(goalRules),"popularity").State);goal.PrepareEquipmentConversation();Good(goal,"resolve_store_event","small");goal.PrepareEquipmentConversation();Finish(goal);Good(goal,"day_off");Check(goal.Simulation.GoalWaiting && goal.OutcomePending && !goal.EquipmentResultPending,"goal after support lost");
   return checks;
  }
  string output;LocalCafeBackend backend;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-support-adv-check");if(i<0)return;var q=new GameObject("Support ADV QA").AddComponent<StandaloneSupportConversationSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  System.Collections.IEnumerator Guard(){var run=Player();while(true){object next;try{if(!run.MoveNext())yield break;next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"failure.txt"),ex.ToString());throw;}yield return next;}}
  static void Apply(PythonStateClient c)=>typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(c,new object[]{(CafeBackends.Local as LocalCafeBackend).View()});
  static UnityEngine.UI.Button Button(EquipmentConversationPanel ui,string caption)=>ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.GetComponentInChildren<UnityEngine.UI.Text>().text==caption);
  System.Collections.IEnumerator Player(){yield return new WaitForSecondsRealtime(1);Run(Path.Combine(output,"backend"));bool restart=Environment.GetCommandLineArgs().Contains("--support-resume");
   backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules());if(restart)Good(backend,"load_game",slot:9);else Setup(backend,true);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;var ui=c.GetComponent<EquipmentConversationPanel>();Check(ui!=null && ui.Showing,"UI absent");
   if(!restart){
    foreach(var caption in new[]{"支援","少額支援","見送り"}){
     var b=new LocalCafeBackend(Path.Combine(output,"ui-"+caption),Rules());Setup(b);CafeBackends.UseLocal(b);Apply(c);b.EquipmentConversation.progress.node=3;Apply(c);yield return null;string facts=Facts(b);Button(ui,caption).onClick.Invoke();yield return null;Check(Button(ui,"取消")!=null,"confirmation absent");Button(ui,"取消").onClick.Invoke();yield return null;Check(Facts(b)==facts && b.Simulation.StoreEventWaiting,"cancel mutates");Button(ui,caption).onClick.Invoke();yield return null;var confirm=Button(ui,"この内容で回答");confirm.onClick.Invoke();confirm.onClick.Invoke();yield return new WaitForSecondsRealtime(1);Apply(c);Check(b.EquipmentResultPending,"UI answer missing");ui.Close();c.GetComponent<PythonEventListPanel>().Store();yield return null;Check(ui.Showing,"list resume missing");
    }
    CafeBackends.UseLocal(backend);Apply(c);yield return null;backend.EquipmentConversation.progress.node=3;Apply(c);yield return null;Good(backend,"save_game",slot:8);Good(backend,"resolve_store_event","small");backend.PrepareEquipmentConversation();backend.EquipmentConversation.progress.node=1;backend.EquipmentConversation.progress.page_offset=0;Good(backend,"save_game",slot:9);
    foreach(var branch in new[]{"full","small","decline"})backend.Replays.Merge(new LocalCafeBackend(Path.Combine(lastRoot,branch),Rules()).Replays.Load().entries);
    string factsBefore=Facts(backend),meta=JsonUtility.ToJson(backend.EquipmentConversations);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();yield return null;
    foreach(var branch in new[]{"full","small","decline"}){extra.OpenReplay(CafeEquipmentDialogue.SupportId+"/"+branch);yield return null;Check(extra.Replay.Showing,"Extra UI missing");for(int n=0;n<40 && extra.Replay.Showing;n++){extra.Replay.Next();yield return null;}extra.Replay.Close();}
    Check(Facts(backend)==factsBefore && JsonUtility.ToJson(backend.EquipmentConversations)==meta,"Extra mutates state");extra.Hide();UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;
   }else Check(backend.EquipmentConversation.progress.node==1 && backend.EquipmentResultPending,"process restart missing");
   Screen.SetResolution(restart?1024:1280,restart?768:800,false);Apply(c);File.WriteAllText(Path.Combine(output,restart?"restart-result.txt":"result.txt"),"PASS: "+checks);ScreenCapture.CaptureScreenshot(Path.Combine(output,restart?"restart.png":"manual-ready.png"));
  }
 }
}
